//! A part-to-whole comparison whose boundaries animate when the data changes.
use crate::components::animated_counter::AnimatedCounter;
use crate::primitives::{
    family::{Paint, Slide, Tone, disabled_motion, face, measure},
    presentation::{column, hint, row, title, tr},
};
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

#[derive(Clone, Debug)]
pub struct SplitSegment {
    pub id: SharedString,
    pub label: SharedString,
    pub value: f64,
    pub color: Hsla,
}
impl SplitSegment {
    pub fn new(
        id: impl Into<SharedString>,
        label: impl Into<SharedString>,
        value: f64,
        color: Hsla,
    ) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            value,
            color,
        }
    }
    fn safe_value(&self) -> f64 {
        if self.value.is_finite() {
            self.value.max(0.)
        } else {
            0.
        }
    }
}
#[derive(Clone, Debug)]
pub struct SplitInspect {
    pub id: SharedString,
    pub value: f64,
    pub share: f64,
}
struct SegmentEdge {
    id: SharedString,
    left: Slide,
    right: Slide,
    outside: Slide,
    label_x: Slide,
    label_y: Slide,
    name: Slide,
    outside_name: Slide,
    inside_counter: Option<Entity<AnimatedCounter>>,
    outside_counter: Option<Entity<AnimatedCounter>>,
    legend_counter: Option<Entity<AnimatedCounter>>,
}
/// Data is host controlled; visibility and the inspected segment are local.
pub struct SplitBar {
    title: SharedString,
    description: SharedString,
    unit: SharedString,
    data: Vec<SplitSegment>,
    hidden: Vec<SharedString>,
    edges: Vec<SegmentEdge>,
    active: Option<usize>,
    bounds: Rc<Cell<Bounds<Pixels>>>,
    initialized: bool,
    layout_ready: bool,
    visible: bool,
    lane: Slide,
    hover_share: f32,
    readout: Option<Entity<AnimatedCounter>>,
}
impl EventEmitter<SplitInspect> for SplitBar {}
impl SplitBar {
    pub fn new(title: impl Into<SharedString>, data: Vec<SplitSegment>) -> Self {
        Self {
            title: title.into(),
            description: "".into(),
            unit: "".into(),
            data,
            hidden: vec![],
            edges: vec![],
            active: None,
            bounds: Default::default(),
            initialized: false,
            layout_ready: false,
            visible: true,
            lane: Slide::new(0.),
            hover_share: 0.,
            readout: None,
        }
    }
    pub fn with_description(mut self, description: impl Into<SharedString>) -> Self {
        self.description = description.into();
        self
    }
    pub fn with_unit(mut self, unit: impl Into<SharedString>) -> Self {
        self.unit = unit.into();
        self
    }
    /// Stop animation scheduling while the embedding host hides the chart.
    pub fn set_visible(&mut self, visible: bool, cx: &mut Context<Self>) {
        if self.visible != visible {
            self.visible = visible;
            cx.notify();
        }
    }
    pub fn set_segments(&mut self, data: Vec<SplitSegment>, cx: &mut Context<Self>) {
        self.data = data;
        self.hidden
            .retain(|id| self.data.iter().any(|s| s.id == *id));
        self.active = None;
        self.reconcile(cx);
        cx.notify();
    }
    fn total(&self) -> f64 {
        self.data
            .iter()
            .filter(|s| !self.hidden.contains(&s.id))
            .map(SplitSegment::safe_value)
            .sum()
    }
    fn shares(&self) -> Vec<f64> {
        normalized_shares(
            &self
                .data
                .iter()
                .map(|segment| {
                    if self.hidden.contains(&segment.id) {
                        0.
                    } else {
                        segment.safe_value()
                    }
                })
                .collect::<Vec<_>>(),
        )
    }
    fn reconcile(&mut self, cx: &App) {
        let base = self.shares();
        let targets = expanded_shares(&base, self.active, self.hover_share);
        let mut left = 0f32;
        let mut previous: Vec<Option<SegmentEdge>> = std::mem::take(&mut self.edges)
            .into_iter()
            .map(Some)
            .collect();
        self.edges = self
            .data
            .iter()
            .enumerate()
            .map(|(index, segment)| {
                let right = (left + targets[index] as f32).min(1.);
                let mut edge = previous
                    .iter()
                    .position(|e| e.as_ref().is_some_and(|v| v.id == segment.id))
                    .and_then(|i| previous[i].take())
                    .unwrap_or_else(|| SegmentEdge {
                        id: segment.id.clone(),
                        left: Slide::new(left),
                        right: Slide::new(if self.initialized { left } else { right }),
                        outside: Slide::new(0.),
                        label_x: Slide::new(0.),
                        label_y: Slide::new(0.),
                        name: Slide::new(1.),
                        outside_name: Slide::new(1.),
                        inside_counter: None,
                        outside_counter: None,
                        legend_counter: None,
                    });
                edge.left.duration(left, 0.4, cx);
                edge.right.duration(right, 0.4, cx);
                left = right;
                edge
            })
            .collect();
        self.initialized = true;
    }
    fn inspect(&mut self, next: Option<usize>, w: &Window, cx: &mut Context<Self>) {
        if self.active == next {
            return;
        }
        self.active = next;
        self.hover_share = next
            .and_then(|index| self.data.get(index))
            .map_or(0., |segment| {
                (measure(&segment.label, 12., w) + 74.)
                    / f32::from(self.bounds.get().size.width).max(1.)
            });
        self.reconcile(cx);
        if let Some(s) = next.and_then(|i| self.data.get(i)) {
            let share = next.map_or(0., |index| self.shares()[index]);
            cx.emit(SplitInspect {
                id: s.id.clone(),
                value: s.safe_value(),
                share,
            });
        }
        cx.notify();
    }
    fn toggle(&mut self, index: usize, cx: &mut Context<Self>) {
        if let Some(s) = self.data.get(index) {
            if let Some(pos) = self.hidden.iter().position(|id| *id == s.id) {
                self.hidden.remove(pos);
            } else if self.data.len().saturating_sub(self.hidden.len()) > 1 {
                self.hidden.push(s.id.clone());
            } else {
                return;
            }
            self.active = None;
            self.reconcile(cx);
            cx.notify();
        }
    }
}
// Normalize before summing to keep finite extreme values proportional.
fn normalized_shares(values: &[f64]) -> Vec<f64> {
    let scale = values.iter().copied().fold(0_f64, f64::max);
    if scale <= 0. {
        return vec![0.; values.len()];
    }
    let total: f64 = values.iter().map(|value| value / scale).sum();
    values.iter().map(|value| (value / scale) / total).collect()
}
fn expanded_shares(base: &[f64], active: Option<usize>, minimum: f32) -> Vec<f64> {
    let Some(index) =
        active.filter(|&i| base.get(i).is_some_and(|value| *value > 0. && *value < 1.))
    else {
        return base.to_vec();
    };
    let target = (base[index] + 0.045)
        .max(f64::from(minimum))
        .min(0.98)
        .max(base[index]);
    let scale = (1. - target) / (1. - base[index]);
    base.iter()
        .enumerate()
        .map(|(i, value)| if i == index { target } else { value * scale })
        .collect()
}

// Pack callouts as a group. A backwards pass reserves room for labels at the
// right edge instead of clamping every label onto the same final position.
fn pack_labels(labels: &[(f32, f32)], width: f32, gap: f32) -> Vec<(f32, f32)> {
    let width = width.max(1.);
    let mut result = vec![(0., 0.); labels.len()];
    let mut start = 0;
    let mut row = 0;
    while start < labels.len() {
        let mut end = start;
        let mut used = 0.;
        while end < labels.len() {
            let next = labels[end].1.min(width);
            if end > start && used + gap + next > width {
                break;
            }
            used += next + if end > start { gap } else { 0. };
            end += 1;
        }
        let mut previous_end = -gap;
        for i in start..end {
            let label_width = labels[i].1.min(width);
            let x = (labels[i].0 - label_width / 2.).max(previous_end + gap);
            result[i] = (x, row as f32 * 24.);
            previous_end = x + label_width;
        }
        let mut next_start = width + gap;
        for i in (start..end).rev() {
            result[i].0 = result[i]
                .0
                .min(next_start - gap - labels[i].1.min(width))
                .max(0.);
            next_start = result[i].0;
        }
        start = end;
        row += 1;
    }
    result
}
fn layout_target(slide: &mut Slide, target: f32, first_layout: bool, cx: &App) {
    if first_layout {
        slide.reset(target);
    } else {
        slide.duration(target, 0.4, cx);
    }
}
impl Render for SplitBar {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        if !self.initialized {
            self.reconcile(cx);
        }
        let p = Paint::get(cx);
        let b = self.bounds.get();
        let width = f32::from(b.size.width).max(1.);
        let first_layout = !self.layout_ready && b.size.width > px(1.);
        let viewport = w.viewport_size();
        let intersects = |b: Bounds<Pixels>| {
            b.size.width > px(0.)
                && b.right() > px(0.)
                && b.left() < viewport.width
                && b.bottom() > px(0.)
                && b.top() < viewport.height
        };
        let visible = self.visible && w.is_visible() && intersects(b);
        let reduced = disabled_motion(cx);
        let now = cx.background_executor().now();
        let mut moving = false;
        let mut sample = |slide: &Slide| {
            let (value, active) = slide.sample_batch(now, reduced);
            moving |= active;
            value
        };
        let base = self.shares();
        let mut lane_needed = false;
        let outside_labels: Vec<_> =
            self.edges
                .iter()
                .enumerate()
                .filter_map(|(i, edge)| {
                    let left = edge.left.sample_batch(now, reduced).0.clamp(0., 1.);
                    let right = edge.right.sample_batch(now, reduced).0.clamp(left, 1.);
                    let name_width = measure(&self.data[i].label, 12., w);
                    let percent_width = measure(&format!("{:.1}%", base[i] * 100.).into(), 12., w);
                    (((right - left) * width - 2. < percent_width + 24.) && base[i] > 0.)
                        .then_some((i, (left + right) * width * 0.5, name_width, percent_width))
                })
                .collect();
        let names_fit = outside_labels
            .iter()
            .map(|(_, _, name, percent)| name + percent + 4.)
            .sum::<f32>()
            + outside_labels.len().saturating_sub(1) as f32 * 12.
            <= width;
        let label_targets = pack_labels(
            &outside_labels
                .iter()
                .map(|(_, center, name, percent)| {
                    (
                        *center,
                        if names_fit {
                            name + 4. + percent
                        } else {
                            *percent
                        },
                    )
                })
                .collect::<Vec<_>>(),
            width,
            12.,
        );
        let mut pieces = Vec::new();
        let mut counter_views = Vec::new();
        for (i, edge) in self.edges.iter_mut().enumerate() {
            let left = sample(&edge.left).clamp(0., 1.);
            let right = sample(&edge.right).clamp(left, 1.);
            let segment = &self.data[i];
            let name_width = measure(&segment.label, 12., w);
            let percent_width = measure(&format!("{:.1}%", base[i] * 100.).into(), 12., w);
            let available = (right - left) * width - 2.;
            let outside = available < percent_width + 24. && base[i] > 0.;
            lane_needed |= outside;
            layout_target(&mut edge.outside, f32::from(outside), first_layout, cx);
            layout_target(
                &mut edge.name,
                f32::from(available >= name_width + percent_width + 30.),
                first_layout,
                cx,
            );
            layout_target(
                &mut edge.outside_name,
                f32::from(names_fit),
                first_layout,
                cx,
            );
            let outside_name = sample(&edge.outside_name).clamp(0., 1.);
            let label_width = (name_width + 4.) * outside_name + percent_width;
            let (label_x, label_y) = outside_labels
                .iter()
                .position(|label| label.0 == i)
                .map_or((0., 0.), |index| label_targets[index]);
            layout_target(&mut edge.label_x, label_x, first_layout, cx);
            layout_target(&mut edge.label_y, label_y, first_layout, cx);
            let outside_progress = sample(&edge.outside);
            let mut counter = |slot: &mut Option<Entity<AnimatedCounter>>,
                               shown: bool,
                               font_size: f32,
                               weight: FontWeight| {
                let view = slot
                    .get_or_insert_with(|| {
                        cx.new(|_| {
                            AnimatedCounter::new(base[i] * 100.)
                                .with_suffix("%")
                                .with_decimals(1)
                                .with_size(font_size)
                                .with_wheel_style(1.2, 0.18, weight)
                                .with_accessibility(false)
                        })
                    })
                    .clone();
                view.update(cx, |view, cx| {
                    view.set_visible(visible && shown, cx);
                    view.set_value(base[i] * 100., cx);
                });
                view
            };
            counter_views.push((
                counter(
                    &mut edge.inside_counter,
                    outside_progress < 0.999,
                    12.,
                    FontWeight::MEDIUM,
                ),
                counter(
                    &mut edge.outside_counter,
                    outside_progress > 0.001,
                    12.,
                    FontWeight::MEDIUM,
                ),
                counter(&mut edge.legend_counter, true, 14., FontWeight::NORMAL),
            ));
            pieces.push((
                left,
                right,
                outside_progress,
                sample(&edge.name),
                sample(&edge.label_x),
                outside_name,
                segment.label.clone(),
                segment.color,
                label_width,
                sample(&edge.label_y),
            ));
        }
        let label_rows = label_targets.iter().map(|(_, y)| *y).fold(0_f32, f32::max);
        layout_target(
            &mut self.lane,
            if lane_needed { 40. + label_rows } else { 0. },
            first_layout,
            cx,
        );
        self.layout_ready |= b.size.width > px(1.);
        let lane = sample(&self.lane).max(0.);
        if visible && moving {
            w.request_animation_frame();
        }
        let pointer_spans: Vec<_> = pieces.iter().map(|piece| (piece.0, piece.1)).collect();
        let active = self.active;
        let bounds = self.bounds.clone();
        let radius = crate::foundation::surface_radius(cx);
        let first_visible = pieces.iter().position(|piece| piece.1 > piece.0);
        let last_visible = pieces.iter().rposition(|piece| piece.1 > piece.0);
        let annotations: Vec<_> = pieces
            .iter()
            .map(|piece| {
                (
                    piece.0,
                    piece.1,
                    piece.2,
                    piece.3,
                    piece.4,
                    piece.5,
                    piece.6.clone(),
                    piece.9,
                )
            })
            .collect();
        let mut graph = div()
            .id("split-bar")
            .role(Role::Figure)
            .tab_index(0)
            .w_full()
            .h(px(44. + lane))
            .relative()
            .aria_label(format!(
                "{}. {}. {}",
                self.title,
                self.data
                    .iter()
                    .enumerate()
                    .map(|(i, segment)| format!("{} {:.1}%", segment.label, base[i] * 100.))
                    .collect::<Vec<_>>()
                    .join(", "),
                tr(
                    cx,
                    "Use arrow keys to inspect segments",
                    "使用方向键查看各部分"
                )
            ))
            .on_hover(cx.listener(|s, hovered: &bool, w, cx| {
                if !hovered {
                    s.inspect(None, w, cx);
                }
            }))
            .on_mouse_move(cx.listener(move |s, e: &MouseMoveEvent, w, cx| {
                let bounds = s.bounds.get();
                if e.position.y > bounds.top() + px(44.) {
                    return;
                }
                let x =
                    f32::from(e.position.x - bounds.left()) / f32::from(bounds.size.width).max(1.);
                let next = pointer_spans
                    .iter()
                    .position(|(left, right)| right > left && x >= *left && x <= *right);
                s.inspect(next, w, cx);
            }))
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|s, e: &MouseDownEvent, w, cx| {
                    let b = s.bounds.get();
                    let x = f32::from(e.position.x - b.left()) / f32::from(b.size.width).max(1.);
                    let next = s
                        .edges
                        .iter()
                        .position(|edge| x >= edge.left.value(cx) && x <= edge.right.value(cx));
                    s.inspect(next, w, cx);
                }),
            )
            .on_key_down(cx.listener(|s, e: &KeyDownEvent, w, cx| {
                let available: Vec<_> = s
                    .data
                    .iter()
                    .enumerate()
                    .filter(|(_, item)| !s.hidden.contains(&item.id))
                    .map(|(i, _)| i)
                    .collect();
                if available.is_empty() {
                    return;
                }
                let at = s
                    .active
                    .and_then(|index| available.iter().position(|i| *i == index));
                let next = match e.keystroke.key.as_str() {
                    "right" | "down" => {
                        Some(available[at.map_or(0, |at| (at + 1) % available.len())])
                    }
                    "left" | "up" => Some(
                        available[at.map_or(available.len() - 1, |at| {
                            (at + available.len() - 1) % available.len()
                        })],
                    ),
                    "home" => available.first().copied(),
                    "end" => available.last().copied(),
                    "escape" => None,
                    _ => return,
                };
                w.prevent_default();
                cx.stop_propagation();
                s.inspect(next, w, cx);
            }))
            .child(
                canvas(
                    move |b, w, _| {
                        let before = bounds.replace(b);
                        let viewport = w.viewport_size();
                        let in_view = |b: Bounds<Pixels>| {
                            b.size.width > px(0.)
                                && b.right() > px(0.)
                                && b.left() < viewport.width
                                && b.bottom() > px(0.)
                                && b.top() < viewport.height
                        };
                        if before.size != b.size || in_view(before) != in_view(b) {
                            w.request_animation_frame();
                        }
                    },
                    move |b, _, w, cx| {
                        let width = f32::from(b.size.width);
                        let paint_text = |text: SharedString,
                                          at: Point<Pixels>,
                                          color: Hsla,
                                          size: f32,
                                          w: &mut Window,
                                          cx: &mut App| {
                            let mut run = w.text_style().to_run(text.len());
                            run.color = color;
                            let line = w.text_system().shape_line(text, px(size), &[run], None);
                            let _ = line.paint(at, px(18.), TextAlign::Left, None, w, cx);
                        };
                        for (
                            i,
                            (
                                left,
                                right,
                                outside,
                                name,
                                label_x,
                                outside_name,
                                label,
                                color,
                                label_width,
                                label_y,
                            ),
                        ) in pieces.iter().enumerate()
                        {
                            let piece_width = ((right - left) * width - 2.).max(0.);
                            if piece_width < 0.1 {
                                continue;
                            }
                            let dim = if active.is_none_or(|active| active == i) {
                                1.
                            } else {
                                0.5
                            };
                            let piece = Bounds::new(
                                point(b.left() + px(left * width), b.top()),
                                size(px(piece_width), px(44.)),
                            );
                            let corners = Corners {
                                top_left: if Some(i) == first_visible {
                                    radius
                                } else {
                                    px(0.)
                                },
                                bottom_left: if Some(i) == first_visible {
                                    radius
                                } else {
                                    px(0.)
                                },
                                top_right: if Some(i) == last_visible {
                                    radius
                                } else {
                                    px(0.)
                                },
                                bottom_right: if Some(i) == last_visible {
                                    radius
                                } else {
                                    px(0.)
                                },
                            };
                            let mix = if active == Some(i) { 0.62 } else { 0.42 };
                            w.paint_quad(
                                fill(piece, p.stage.blend(color.opacity(mix)).opacity(dim))
                                    .corner_radii(corners),
                            );
                            if Some(i) != last_visible {
                                w.paint_quad(fill(
                                    Bounds::new(
                                        point(piece.right() - px(3.), piece.top()),
                                        size(px(3.), px(44.)),
                                    ),
                                    color.opacity(dim),
                                ));
                            }
                            w.with_content_mask(Some(ContentMask { bounds: piece }), |w| {
                                let x = piece.left() + px(10.);
                                let name_width = measure(label, 12., w) * name;
                                if *name > 0.001 {
                                    let name_bounds = Bounds::new(
                                        point(x, piece.top()),
                                        size(px(name_width), piece.size.height),
                                    )
                                    .intersect(&piece);
                                    w.with_content_mask(
                                        Some(ContentMask {
                                            bounds: name_bounds,
                                        }),
                                        |w| {
                                            paint_text(
                                                label.clone(),
                                                point(x, piece.top() + px(13.)),
                                                p.ink.opacity(dim * (1. - outside) * name),
                                                12.,
                                                w,
                                                cx,
                                            );
                                        },
                                    );
                                }
                            });
                            if *outside > 0.001 {
                                let center = (left + right) * width * 0.5;
                                let end = label_x + label_width * 0.5;
                                let mut path = PathBuilder::stroke(px(1.));
                                path.move_to(point(b.left() + px(center), b.top() + px(44.)));
                                path.cubic_bezier_to(
                                    point(b.left() + px(end), b.top() + px(59. + label_y)),
                                    point(b.left() + px(center), b.top() + px(54.)),
                                    point(b.left() + px(end), b.top() + px(50. + label_y)),
                                );
                                if let Ok(path) = path.build() {
                                    w.paint_path(
                                        path,
                                        p.faint.opacity(outside * if dim < 1. { 0.4 } else { 1. }),
                                    );
                                }
                                if *outside_name > 0.001 {
                                    paint_text(
                                        label.clone(),
                                        point(b.left() + px(*label_x), b.top() + px(60. + label_y)),
                                        p.ink.opacity(
                                            outside
                                                * outside_name
                                                * if dim < 1. { 0.45 } else { 1. },
                                        ),
                                        12.,
                                        w,
                                        cx,
                                    );
                                }
                            }
                        }
                    },
                )
                .size_full(),
            );
        for (
            (left, right, outside, name, label_x, outside_name, label, label_y),
            (inside, outside_view, _),
        ) in annotations.into_iter().zip(&counter_views)
        {
            let piece_width = ((right - left) * width - 2.).max(0.);
            if piece_width < 0.1 {
                continue;
            }
            graph = graph
                .child(
                    div()
                        .absolute()
                        .left(px(left * width))
                        .top_0()
                        .w(px(piece_width))
                        .h(px(44.))
                        .overflow_hidden()
                        .child(
                            div()
                                .absolute()
                                .left(px(10. + (measure(&label, 12., w) + 4.) * name))
                                .top(px(15.5))
                                .opacity(1. - outside)
                                .child(inside.clone()),
                        ),
                )
                .child(
                    div()
                        .absolute()
                        .left(px(label_x + (measure(&label, 12., w) + 4.) * outside_name))
                        .top(px(62.5 + label_y))
                        .opacity(outside)
                        .child(outside_view.clone()),
                );
        }
        let total = self.total();
        let value = self
            .active
            .map_or(total, |index| self.data[index].safe_value());
        let readout = self
            .readout
            .get_or_insert_with(|| {
                cx.new(|_| {
                    AnimatedCounter::new(value)
                        .with_size(18.)
                        .with_wheel_style(1.2, 0.18, FontWeight::MEDIUM)
                        .with_accessibility(false)
                })
            })
            .clone();
        readout.update(cx, |counter, cx| {
            counter.set_visible(visible, cx);
            counter.set_value(value, cx);
        });
        let detail: SharedString = self.active.map_or_else(
            || tr(cx, "Total", "总计").into(),
            |index| self.data[index].label.clone(),
        );
        column()
            .w(px(520.))
            .max_w_full()
            .gap(px(12.))
            .text_color(p.ink)
            .child(
                row()
                    .flex_wrap()
                    .justify_between()
                    .gap(px(12.))
                    .child(
                        column()
                            .gap(px(2.))
                            .child(title(self.title.clone(), p))
                            .when(!self.description.is_empty(), |view| {
                                view.child(
                                    hint(self.description.clone(), p)
                                        .text_size(px(14.))
                                        .line_height(px(19.6)),
                                )
                            }),
                    )
                    .child(
                        row()
                            .items_baseline()
                            .gap(px(8.))
                            .child(hint(detail, p).text_size(px(14.)).line_height(px(20.)))
                            .when(value.is_finite(), |view| view.child(readout))
                            .when(!value.is_finite(), |view| view.child(">1.8e308"))
                            .when(!self.unit.is_empty(), |view| {
                                view.child(
                                    hint(self.unit.clone(), p)
                                        .text_size(px(14.))
                                        .line_height(px(20.)),
                                )
                            }),
                    ),
            )
            .child(graph)
            .child(row().flex_wrap().ml(px(-8.)).gap_x(px(4.)).gap_y(px(2.)).children(
                self.data.iter().enumerate().map(|(i, segment)| {
                    let off = self.hidden.contains(&segment.id);
                    let label = format!(
                        "{}  {}",
                        segment.label,
                        if off {
                            tr(cx, "Off", "已隐藏").to_owned()
                        } else {
                            format!("{:.1}%", base[i] * 100.)
                        }
                    );
                    face(
                        ("split-segment", i),
                        label.clone(),
                        32.,
                        radius.into(),
                        Tone::Clear,
                        cx,
                    )
                    .pl(px(8.))
                    .pr(px(10.))
                    .aria_toggled((!off).into())
                    .gap(px(8.))
                    .text_size(px(14.))
                    .line_height(px(20.))
                    .font_weight(FontWeight::NORMAL)
                    .hover(|s| s.bg(p.tray))
                    .child(
                        div()
                            .relative()
                            .size(px(12.))
                            .flex_none()
                            .rounded(px(3.))
                            .when(off, |view| view.border(px(1.5)).border_color(p.faint))
                            .when(!off, |view| {
                                view.bg(p.panel.blend(segment.color.opacity(0.42))).child(
                                    div()
                                        .absolute()
                                        .right_0()
                                        .top_0()
                                        .bottom_0()
                                        .w(px(3.))
                                        .bg(segment.color),
                                )
                            }),
                    )
                    .child(segment.label.clone())
                    .when(off, |view| view.child(tr(cx, "Off", "已隐藏")))
                    .when(!off, |view| view.child(counter_views[i].2.clone()))
                    .on_click(cx.listener(move |s, _, _, cx| s.toggle(i, cx)))
                }),
            ))
    }
}
#[cfg(test)]
mod tests {
    use super::{expanded_shares, normalized_shares, pack_labels};
    #[test]
    fn large_finite_values_keep_their_proportions() {
        let normalized = normalized_shares(&[f64::MAX, f64::MAX, f64::MAX / 2.]);
        assert!((normalized[0] - 0.4).abs() < 1e-12);
        assert!((normalized[2] - 0.2).abs() < 1e-12);
    }
    #[test]
    fn inspection_gives_space_without_changing_the_whole() {
        let base = normalized_shares(&[40., 30., 29., 1.]);
        let expanded = expanded_shares(&base, Some(3), 0.2);
        assert!((expanded.iter().sum::<f64>() - 1.).abs() < 1e-12);
        assert!((expanded[3] - 0.2).abs() < 1e-7);
        assert!((expanded[0] / expanded[1] - base[0] / base[1]).abs() < 1e-12);
    }
    #[test]
    fn hidden_segments_do_not_reserve_empty_gaps() {
        let result = expanded_shares(&normalized_shares(&[0., 20., 80.]), Some(1), 0.3);
        assert_eq!(result[0], 0.);
        assert!((result.iter().sum::<f64>() - 1.).abs() < 1e-12);
    }

    #[test]
    fn right_edge_callouts_reserve_space_for_the_whole_cluster() {
        let labels = [(450., 82.), (490., 91.), (515., 70.)];
        let packed = pack_labels(&labels, 520., 12.);
        assert!(packed[0].0 >= 0.);
        for i in 1..packed.len() {
            assert!(packed[i].0 >= packed[i - 1].0 + labels[i - 1].1 + 12.);
        }
        assert!(packed[2].0 + labels[2].1 <= 520.);
    }

    #[test]
    fn narrow_callouts_keep_every_percentage_inside_its_lane() {
        let labels: Vec<_> = (0..8).map(|i| (i as f32 * 29. + 14.5, 33.)).collect();
        let packed = pack_labels(&labels, 232., 12.);
        for (i, &(x, y)) in packed.iter().enumerate() {
            assert!(x >= 0. && x + labels[i].1 <= 232.);
            if i > 0 && y == packed[i - 1].1 {
                assert!(x >= packed[i - 1].0 + labels[i - 1].1 + 12.);
            }
        }
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

